import React, { useEffect, useState } from 'react';
import WorkgroupTree from './WorkgroupTree';
import CreateChildWorkgroupModal from './CreateChildWorkgroupModal';
import MoveWorkgroupModal from './MoveWorkgroupModal';
import DeleteWorkgroupConfirmation from './DeleteWorkgroupConfirmation';
import WorkgroupBreadcrumb from './WorkgroupBreadcrumb';
import WorkgroupManagement from './WorkgroupManagement';
import { getWorkgroupById, isAwsWorkgroup, type WorkgroupResponse } from '../services/workgroupApi';
import { useClientHasRole } from '../utils/useClientAuth';
import { formatServerDateTime } from '../utils/dateUtils';

/**
 * Enhanced Workgroup Management Component with Hierarchy Support
 * Feature 040: Nested Workgroups
 *
 * Combines existing flat workgroup management with new hierarchy features:
 * - Tree view with expand/collapse
 * - Breadcrumb navigation
 * - Create child workgroups
 * - Move workgroups
 * - Delete with child promotion
 *
 * Maintains backward compatibility with existing user/asset assignment features.
 */

const WorkgroupManagementWithHierarchy: React.FC = () => {
  const [viewMode, setViewMode] = useState<'tree' | 'table'>('table');
  const [selectedWorkgroup, setSelectedWorkgroup] = useState<WorkgroupResponse | null>(null);
  const [showCreateChildModal, setShowCreateChildModal] = useState(false);
  const [parentForChild, setParentForChild] = useState<WorkgroupResponse | null>(null);
  const [showMoveModal, setShowMoveModal] = useState(false);
  const [workgroupToMove, setWorkgroupToMove] = useState<WorkgroupResponse | null>(null);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [workgroupToDelete, setWorkgroupToDelete] = useState<WorkgroupResponse | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  // AD-imported workgroups (names starting "AWS-") are hidden by default; this
  // toggle reveals them in both the tree and table views.
  const [showAwsWorkgroups, setShowAwsWorkgroups] = useState(false);

  // Keep hierarchy mutations on the same grant-manager boundary as the backend.
  const canCreateChild = useClientHasRole(['ADMIN', 'SECCHAMPION']);

  useEffect(() => {
    const rawId = new URLSearchParams(window.location.search).get('workgroupId');
    if (!rawId || !/^\d+$/.test(rawId)) return;

    const workgroupId = Number(rawId);
    getWorkgroupById(workgroupId)
      .then((workgroup) => {
        setSelectedWorkgroup(workgroup);
        setViewMode('tree');
        if (isAwsWorkgroup(workgroup.name)) setShowAwsWorkgroups(true);
      })
      .catch((error) => console.error('Failed to open linked workgroup details:', error));
  }, []);

  const handleSelectWorkgroup = (workgroup: WorkgroupResponse) => {
    setSelectedWorkgroup(workgroup);
  };

  const handleCreateChild = (parent: WorkgroupResponse) => {
    setParentForChild(parent);
    setShowCreateChildModal(true);
  };

  const handleChildCreated = (child: WorkgroupResponse) => {
    setRefreshTrigger(prev => prev + 1); // Trigger tree refresh
    setSelectedWorkgroup(child); // Select the newly created child
  };

  const handleMoveWorkgroup = (workgroup: WorkgroupResponse) => {
    setWorkgroupToMove(workgroup);
    setShowMoveModal(true);
  };

  const handleWorkgroupMoved = (movedWorkgroup: WorkgroupResponse) => {
    setRefreshTrigger(prev => prev + 1); // Trigger tree refresh
    setSelectedWorkgroup(movedWorkgroup); // Select the moved workgroup
  };

  const handleDeleteWorkgroup = (workgroup: WorkgroupResponse) => {
    setWorkgroupToDelete(workgroup);
    setShowDeleteModal(true);
  };

  const handleWorkgroupDeleted = () => {
    setRefreshTrigger(prev => prev + 1); // Trigger tree refresh
    setSelectedWorkgroup(null); // Clear selection
  };

  return (
    <div
      className="container-fluid mt-4 d-flex flex-column"
      style={{ height: 'calc(100dvh - 9.5rem)', minHeight: 0, overflow: 'hidden' }}
    >
      {/* Header with view toggle */}
      <div className="d-flex justify-content-between align-items-center mb-4 flex-shrink-0">
        <h2>
          <i className="bi bi-diagram-3 me-2"></i>
          Workgroup Management
        </h2>
        <div className="d-flex align-items-center gap-3">
          <div className="form-check form-switch mb-0">
            <input
              className="form-check-input"
              type="checkbox"
              id="showAwsWorkgroups"
              checked={showAwsWorkgroups}
              onChange={(e) => setShowAwsWorkgroups(e.target.checked)}
            />
            <label className="form-check-label" htmlFor="showAwsWorkgroups">
              Show AWS- workgroups
            </label>
          </div>
          <div className="btn-group" role="group">
            <button
              type="button"
              className={`btn ${viewMode === 'tree' ? 'btn-primary' : 'btn-outline-primary'}`}
              onClick={() => setViewMode('tree')}
            >
              <i className="bi bi-diagram-3"></i> Tree View
            </button>
            <button
              type="button"
              className={`btn ${viewMode === 'table' ? 'btn-primary' : 'btn-outline-primary'}`}
              onClick={() => setViewMode('table')}
            >
              <i className="bi bi-table"></i> Table View
            </button>
          </div>
        </div>
      </div>

      {/* Tree View */}
      {viewMode === 'tree' && (
        <div className="row flex-grow-1 overflow-auto" style={{ minHeight: 0, overscrollBehavior: 'contain' }}>
          {/* Left Panel: Tree */}
          <div className="col-md-5">
            <div className="card">
              <div className="card-body">
                <WorkgroupTree
                  key={refreshTrigger} // Force refresh when trigger changes
                  onSelectWorkgroup={handleSelectWorkgroup}
                  onCreateChild={canCreateChild ? handleCreateChild : undefined}
                  selectedWorkgroupId={selectedWorkgroup?.id}
                  showAwsWorkgroups={showAwsWorkgroups}
                />
              </div>
            </div>
          </div>

          {/* Right Panel: Selected Workgroup Details */}
          <div className="col-md-7">
            {selectedWorkgroup ? (
              <div className="card">
                <div className="card-header bg-primary text-white">
                  <h5 className="mb-0">
                    <i className="bi bi-folder2-open me-2"></i>
                    Workgroup Details
                  </h5>
                </div>
                <div className="card-body">
                  {/* Breadcrumb */}
                  <WorkgroupBreadcrumb
                    workgroup={selectedWorkgroup}
                    onNavigate={(id) => {
                      // Navigate to workgroup by ID
                      // In a real app, you'd fetch the workgroup and select it
                      console.log('Navigate to workgroup:', id);
                    }}
                  />

                  <hr />

                  {/* Workgroup Information */}
                  <div className="row mb-3">
                    <div className="col-md-6">
                      <h4>{selectedWorkgroup.name}</h4>
                      {selectedWorkgroup.description && (
                        <p className="text-muted">{selectedWorkgroup.description}</p>
                      )}
                    </div>
                    <div className="col-md-6 text-end">
                      <div className="mb-2">
                        <span className="badge bg-secondary me-2">
                          Level {selectedWorkgroup.depth} / 5
                        </span>
                        {selectedWorkgroup.hasChildren && (
                          <span className="badge bg-info">
                            {selectedWorkgroup.childCount} child{selectedWorkgroup.childCount === 1 ? '' : 'ren'}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Hierarchy Actions */}
                  <div className="mb-3">
                    <h6 className="text-muted">Hierarchy Actions</h6>
                    <div className="btn-group btn-group-sm">
                      {canCreateChild && selectedWorkgroup.depth < 5 && (
                        <button
                          className="btn btn-outline-primary"
                          onClick={() => handleCreateChild(selectedWorkgroup)}
                        >
                          <i className="bi bi-plus-circle me-1"></i>
                          Add Child
                        </button>
                      )}
                      <button
                        className="btn btn-outline-secondary"
                        disabled={!canCreateChild}
                        onClick={() => handleMoveWorkgroup(selectedWorkgroup)}
                      >
                        <i className="bi bi-arrows-move me-1"></i>
                        Move
                      </button>
                      <button
                        className="btn btn-outline-danger"
                        disabled={!canCreateChild}
                        onClick={() => handleDeleteWorkgroup(selectedWorkgroup)}
                      >
                        <i className="bi bi-trash me-1"></i>
                        Delete
                      </button>
                    </div>
                  </div>

                  {/* Metadata */}
                  <div className="border-top pt-3">
                    <h6 className="text-muted">Metadata</h6>
                    <dl className="row mb-0 small">
                      <dt className="col-sm-4">ID</dt>
                      <dd className="col-sm-8">{selectedWorkgroup.id}</dd>

                      <dt className="col-sm-4">Parent ID</dt>
                      <dd className="col-sm-8">
                        {selectedWorkgroup.parentId ?? <span className="text-muted">None (Root level)</span>}
                      </dd>

                      <dt className="col-sm-4">Status</dt>
                      <dd className="col-sm-8">
                        <span className={`badge ${selectedWorkgroup.enabled !== false ? 'bg-success' : 'bg-secondary'}`}>
                          {selectedWorkgroup.enabled !== false ? 'Enabled' : 'Disabled'}
                        </span>
                      </dd>

                      <dt className="col-sm-4">Created</dt>
                      <dd className="col-sm-8">
                        {formatServerDateTime(selectedWorkgroup.createdAt)}
                      </dd>

                      <dt className="col-sm-4">Updated</dt>
                      <dd className="col-sm-8">
                        {formatServerDateTime(selectedWorkgroup.updatedAt)}
                      </dd>

                      <dt className="col-sm-4">Version</dt>
                      <dd className="col-sm-8">
                        {selectedWorkgroup.version} <span className="text-muted">(optimistic locking)</span>
                      </dd>
                    </dl>
                  </div>

                  {/* Ancestor Path */}
                  {selectedWorkgroup.ancestors?.length > 0 && (
                    <div className="border-top pt-3 mt-3">
                      <h6 className="text-muted">Ancestor Path</h6>
                      <div className="d-flex flex-wrap gap-2">
                        {selectedWorkgroup.ancestors.map((ancestor, index) => (
                          <React.Fragment key={ancestor.id}>
                            <span className="badge bg-light text-dark border">
                              {ancestor.name}
                            </span>
                            {index < selectedWorkgroup.ancestors.length - 1 && (
                              <i className="bi bi-chevron-right text-muted"></i>
                            )}
                          </React.Fragment>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="card">
                <div className="card-body text-center py-5 text-muted">
                  <i className="bi bi-folder2-open" style={{ fontSize: '48px' }}></i>
                  <p className="mt-3">Select a workgroup from the tree to view details</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Table View (Existing Flat View) */}
      {viewMode === 'table' && (
        <div className="d-flex flex-column flex-grow-1" style={{ minHeight: 0 }}>
          <div className="alert alert-info mb-3 flex-shrink-0">
            <i className="bi bi-info-circle"></i>
            <strong> Table View:</strong> This is the classic flat view of all workgroups. Switch to Tree View to see the hierarchy.
          </div>
          <WorkgroupManagement showAwsWorkgroups={showAwsWorkgroups} />
        </div>
      )}

      {/* Modals */}
      <CreateChildWorkgroupModal
        show={showCreateChildModal}
        parentWorkgroup={parentForChild}
        onClose={() => {
          setShowCreateChildModal(false);
          setParentForChild(null);
        }}
        onSuccess={handleChildCreated}
      />

      <MoveWorkgroupModal
        show={showMoveModal}
        workgroup={workgroupToMove}
        onClose={() => {
          setShowMoveModal(false);
          setWorkgroupToMove(null);
        }}
        onSuccess={handleWorkgroupMoved}
      />

      <DeleteWorkgroupConfirmation
        show={showDeleteModal}
        workgroup={workgroupToDelete}
        onClose={() => {
          setShowDeleteModal(false);
          setWorkgroupToDelete(null);
        }}
        onSuccess={handleWorkgroupDeleted}
      />
    </div>
  );
};

export default WorkgroupManagementWithHierarchy;
import React, { useState, useEffect } from 'react';
import { getJson, ApiError, deleteJson, putJson } from '../utils/apiJson';
import WorkgroupAccountsModal from './WorkgroupAccountsModal';
import WorkgroupDomainsModal from './WorkgroupDomainsModal';
import WorkgroupFormModal from './WorkgroupFormModal';
import WorkgroupAssignUsersModal from './WorkgroupAssignUsersModal';
import WorkgroupAssignAssetsModal from './WorkgroupAssignAssetsModal';
import { isAwsWorkgroup } from '../services/workgroupApi';
import { formatServerDate } from '../utils/dateUtils';
import { useClientHasRole } from '../utils/useClientAuth';
import { scrollContainerStyle, stickyHeaderCellStyle } from './scrollableTableStyles';
import type { Workgroup, WorkgroupAsset, WorkgroupUser } from './workgroupTypes';

interface WorkgroupManagementProps {
  /** When false (default), workgroups named "AWS-…" are hidden from the table. */
  showAwsWorkgroups?: boolean;
}

/**
 * Workgroup admin screen: the table plus launcher state for the five dialogs.
 * Each dialog (create/edit form, assign users, manage assets, AWS accounts,
 * AD domains) is its own component owning its modal-scoped state; this parent
 * fetches the shared lists, renders the table, and refetches after saves.
 */
const WorkgroupManagement: React.FC<WorkgroupManagementProps> = ({ showAwsWorkgroups = false }) => {
  const [workgroups, setWorkgroups] = useState<Workgroup[]>([]);
  const [users, setUsers] = useState<WorkgroupUser[]>([]);
  const [assets, setAssets] = useState<WorkgroupAsset[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [editingWorkgroup, setEditingWorkgroup] = useState<Workgroup | null>(null);
  const [assignUsersWorkgroup, setAssignUsersWorkgroup] = useState<Workgroup | null>(null);
  const [assignAssetsWorkgroup, setAssignAssetsWorkgroup] = useState<Workgroup | null>(null);
  const [accountsModalState, setAccountsModalState] = useState<{
    isOpen: boolean;
    workgroupId: number | null;
    workgroupName: string;
  }>({ isOpen: false, workgroupId: null, workgroupName: '' });
  const [domainsModalState, setDomainsModalState] = useState<{
    isOpen: boolean;
    workgroupId: number | null;
    workgroupName: string;
  }>({ isOpen: false, workgroupId: null, workgroupName: '' });
  const canChangeStatus = useClientHasRole(['ADMIN', 'SECCHAMPION']);

  useEffect(() => {
    fetchWorkgroups();
    fetchUsers();
    fetchAssets();
  }, []);

  const fetchWorkgroups = async () => {
    try {
      setWorkgroups(await getJson<Workgroup[]>('/api/workgroups', 'Failed to fetch workgroups'));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  const fetchUsers = async () => {
    // Self-service workgroup management is open to non-ADMIN members; the canonical
    // /api/users list is ADMIN-only. The aws-account-sharing endpoint is the established
    // non-admin-safe user list (same {id, username, email, isPending} shape).
    // See AwsAccountSharingController.listUsersForSharing — deprecated pending a generic
    // public-safe replacement on /api/users.
    try {
      setUsers(await getJson<WorkgroupUser[]>('/api/aws-account-sharing/users', 'Failed to fetch users'));
    } catch (err) {
      console.error('Failed to fetch users:', err);
    }
  };

  const fetchAssets = async () => {
    try {
      setAssets(await getJson<WorkgroupAsset[]>('/api/assets', 'Failed to fetch assets'));
    } catch (err) {
      console.error('Failed to fetch assets:', err);
    }
  };

  const handleDelete = async (id: number) => {
    if (!window.confirm('Are you sure you want to delete this workgroup? This will remove all user and asset assignments.')) {
      return;
    }

    try {
      await deleteJson(`/api/workgroups/${id}`, undefined, 'Failed to delete workgroup');
      await fetchWorkgroups();
      setError(null);
    } catch (err) {
      const message = err instanceof ApiError || err instanceof Error
        ? err.message
        : 'An error occurred while deleting the workgroup';
      setError(message);
    }
  };

  const handleStatusChange = async (workgroup: Workgroup) => {
    const nextEnabled = workgroup.enabled === false;
    if (!nextEnabled && !window.confirm(
      `Disable ${workgroup.name}? Its users, assets, accounts, and domains will remain stored but will no longer grant access.`
    )) {
      return;
    }

    try {
      await putJson(`/api/workgroups/${workgroup.id}`, { enabled: nextEnabled }, 'Failed to update workgroup status');
      await fetchWorkgroups();
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred while updating the workgroup status');
    }
  };

  const closeForm = () => {
    setShowForm(false);
    setEditingWorkgroup(null);
  };

  if (loading) {
    return <div className="text-center p-4">Loading workgroups...</div>;
  }

  return (
    <div className="container-fluid mt-4 d-flex flex-column flex-grow-1" style={{ minHeight: 0 }}>
      <div className="d-flex justify-content-between align-items-center mb-4 flex-shrink-0">
        <h2>Workgroup Management</h2>
        <button disabled={!canChangeStatus} className="btn btn-primary" onClick={() => setShowForm(true)}>
          Create Workgroup
        </button>
      </div>

      {error && (
        <div className="alert alert-danger alert-dismissible fade show" role="alert">
          {error}
          <button type="button" className="btn-close" onClick={() => setError(null)}></button>
        </div>
      )}

      {/* Create/Edit Form Modal */}
      {showForm && (
        <WorkgroupFormModal
          workgroup={editingWorkgroup}
          onClose={closeForm}
          onSaved={async () => {
            await fetchWorkgroups();
            closeForm();
            setError(null);
          }}
          onError={setError}
        />
      )}

      {/* Assign Users Modal */}
      {assignUsersWorkgroup && (
        <WorkgroupAssignUsersModal
          workgroup={assignUsersWorkgroup}
          users={users}
          onClose={() => setAssignUsersWorkgroup(null)}
          onSaved={async () => {
            await fetchWorkgroups();
            setAssignUsersWorkgroup(null);
            setError(null);
          }}
          onError={setError}
        />
      )}

      {/* Manage Assets Modal */}
      {assignAssetsWorkgroup && (
        <WorkgroupAssignAssetsModal
          workgroup={assignAssetsWorkgroup}
          assets={assets}
          onClose={() => setAssignAssetsWorkgroup(null)}
          onSaved={async () => {
            await fetchWorkgroups();
            setAssignAssetsWorkgroup(null);
            setError(null);
          }}
          onError={setError}
        />
      )}

      {/* Accounts Modal */}
      {accountsModalState.workgroupId !== null && (
        <WorkgroupAccountsModal
          workgroupId={accountsModalState.workgroupId}
          workgroupName={accountsModalState.workgroupName}
          isOpen={accountsModalState.isOpen}
          onClose={() =>
            setAccountsModalState({ isOpen: false, workgroupId: null, workgroupName: '' })
          }
          onChange={() => {
            fetchWorkgroups();
          }}
        />
      )}

      {/* Domains Modal */}
      {domainsModalState.workgroupId !== null && (
        <WorkgroupDomainsModal
          workgroupId={domainsModalState.workgroupId}
          workgroupName={domainsModalState.workgroupName}
          isOpen={domainsModalState.isOpen}
          onClose={() =>
            setDomainsModalState({ isOpen: false, workgroupId: null, workgroupName: '' })
          }
          onChange={() => {
            fetchWorkgroups();
          }}
        />
      )}

      {/* Workgroups Table */}
      <div className="table-responsive flex-grow-1" style={scrollContainerStyle}>
        <table className="table table-striped table-hover" style={{ borderCollapse: 'separate', borderSpacing: 0 }}>
          <thead className="table-light">
            <tr>
              <th style={stickyHeaderCellStyle}>Parent</th>
              <th style={stickyHeaderCellStyle}>Name</th>
              <th style={stickyHeaderCellStyle}>AD Owner</th>
              <th style={stickyHeaderCellStyle}>Status</th>
              <th style={stickyHeaderCellStyle}>Users</th>
              <th style={stickyHeaderCellStyle}>Assets</th>
              <th style={stickyHeaderCellStyle}>Accounts</th>
              <th style={stickyHeaderCellStyle}>Domains</th>
              <th style={stickyHeaderCellStyle}>Created</th>
              <th style={stickyHeaderCellStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {(() => {
              const visibleWorkgroups = workgroups.filter(
                wg => showAwsWorkgroups || !isAwsWorkgroup(wg.name)
              );
              const hiddenAwsCount = workgroups.length - visibleWorkgroups.length;
              return visibleWorkgroups.length === 0 ? (
              <tr>
                <td colSpan={10} className="text-center text-muted">
                  {hiddenAwsCount > 0
                    ? 'AWS- workgroups are hidden. Enable "Show AWS- workgroups" to see them.'
                    : 'No visible workgroups found.'}
                </td>
              </tr>
            ) : (
              visibleWorkgroups.map(workgroup => {
                const enabled = workgroup.enabled !== false;
                return (
                  <tr key={workgroup.id} className={enabled ? undefined : 'table-secondary'}>
                    <td>
                      {workgroup.parentName
                        ? workgroup.parentName
                        : <span className="text-muted fst-italic">root</span>}
                    </td>
                    <td><strong>{workgroup.name}</strong></td>
                    <td>
                      {workgroup.ownerEmail ?? <span className="text-muted fst-italic">not set</span>}
                    </td>
                    <td>
                      <span className={`badge ${enabled ? 'bg-success' : 'bg-secondary'}`}>
                        {enabled ? 'Enabled' : 'Disabled'}
                      </span>
                    </td>
                    <td>
                      <span className="badge bg-info">{workgroup.userCount}</span>
                    </td>
                    <td>
                      <span className="badge bg-success">{workgroup.assetCount}</span>
                    </td>
                    <td>
                      <span className="badge bg-secondary">{workgroup.awsAccountsCount ?? 0}</span>
                    </td>
                    <td>
                      <span className="badge bg-secondary">{workgroup.adDomainsCount ?? 0}</span>
                    </td>
                    <td>{formatServerDate(workgroup.createdAt)}</td>
                  <td>
                    <fieldset disabled={!canChangeStatus} className="btn-group btn-group-sm">
                      <button
                        className="btn btn-outline-primary"
                        onClick={() => {
                          setEditingWorkgroup(workgroup);
                          setShowForm(true);
                        }}
                        title="Edit workgroup"
                      >
                        Edit
                      </button>
                      <button
                        className="btn btn-outline-info"
                        onClick={() => setAssignUsersWorkgroup(workgroup)}
                        title="Assign users"
                      >
                        Users
                      </button>
                      <button
                        type="button"
                        className="btn btn-sm btn-info ms-1"
                        onClick={() =>
                          setAccountsModalState({
                            isOpen: true,
                            workgroupId: workgroup.id,
                            workgroupName: workgroup.name,
                          })
                        }
                        title="Manage AWS accounts"
                      >
                        Accounts
                      </button>
                      <button
                        type="button"
                        className="btn btn-sm btn-secondary ms-1"
                        onClick={() =>
                          setDomainsModalState({
                            isOpen: true,
                            workgroupId: workgroup.id,
                            workgroupName: workgroup.name,
                          })
                        }
                        title="Manage AD domains"
                      >
                        Domains
                      </button>
                      <button
                        className="btn btn-outline-success"
                        onClick={() => setAssignAssetsWorkgroup(workgroup)}
                        title="Manage assets"
                      >
                        Assets
                      </button>
                      {canChangeStatus && (
                        <button
                          className={`btn ${enabled ? 'btn-outline-warning' : 'btn-outline-success'}`}
                          onClick={() => handleStatusChange(workgroup)}
                          title={`${enabled ? 'Disable' : 'Enable'} workgroup`}
                        >
                          {enabled ? 'Disable' : 'Enable'}
                        </button>
                      )}
                      <button
                        className="btn btn-outline-danger"
                        onClick={() => handleDelete(workgroup.id)}
                        title="Delete workgroup"
                      >
                        Delete
                      </button>
                    </fieldset>
                  </td>
                </tr>
                );
              })
            );
            })()}
          </tbody>
        </table>
      </div>
    </div>
  );
};

