 * pure logic in workgroupAssignLogic.ts.
 */

export type WorkgroupCriticality = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NA';

/** A workgroup row as the management table receives it from GET /api/workgroups. */
export interface Workgroup {
    id: number;
    name: string;
    description?: string;
