import React, { useState, useEffect } from 'react';
import type { WorkgroupResponse } from '../services/workgroupApi';
import { getWorkgroupChildren, getRootWorkgroups, isAwsWorkgroup } from '../services/workgroupApi';

/**
 * Workgroup Tree Component
 * Feature 040: Nested Workgroups (User Story 2 & 5)
 *
 * Displays hierarchical workgroup tree with:
 * - Expand/collapse functionality
 * - Lazy loading of children
 * - Breadcrumb navigation
 * - Visual depth indicators
 */

interface WorkgroupTreeProps {
  onSelectWorkgroup?: (workgroup: WorkgroupResponse) => void;
  onCreateChild?: (parent: WorkgroupResponse) => void;
  selectedWorkgroupId?: number | null;
  /** When false (default), workgroups named "AWS-…" are hidden. */
  showAwsWorkgroups?: boolean;
}

interface TreeNodeProps {
  workgroup: WorkgroupResponse;
  level: number;
  onSelectWorkgroup?: (workgroup: WorkgroupResponse) => void;
  onCreateChild?: (parent: WorkgroupResponse) => void;
  selectedWorkgroupId?: number | null;
  showAwsWorkgroups?: boolean;
}

const TreeNode: React.FC<TreeNodeProps> = ({
  workgroup,
  level,
  onSelectWorkgroup,
  onCreateChild,
  selectedWorkgroupId,
  showAwsWorkgroups
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [children, setChildren] = useState<WorkgroupResponse[]>([]);
  const [loadingChildren, setLoadingChildren] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChildren = workgroup.hasChildren || workgroup.childCount > 0;
  const isSelected = selectedWorkgroupId === workgroup.id;

  const toggleExpand = async () => {
    if (!hasChildren) return;

    if (!isExpanded && children.length === 0) {
      // Lazy load children
      setLoadingChildren(true);
      setError(null);
      try {
        const childWorkgroups = await getWorkgroupChildren(workgroup.id);
        setChildren(childWorkgroups);
        setIsExpanded(true);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load children');
        console.error('Failed to load children:', err);
      } finally {
        setLoadingChildren(false);
      }
    } else {
      setIsExpanded(!isExpanded);
    }
  };

  const handleSelect = () => {
    if (onSelectWorkgroup) {
      onSelectWorkgroup(workgroup);
    }
  };

  const handleCreateChild = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onCreateChild) {
      onCreateChild(workgroup);
    }
  };

  const indentStyle = {
    marginLeft: `${level * 20}px`
  };

  return (
    <div>
      <div
        className={`d-flex align-items-center py-2 px-3 border-bottom ${isSelected ? 'bg-primary bg-opacity-10' : 'hover-bg-light'} ${workgroup.enabled === false ? 'text-muted bg-light' : ''}`}
        style={{ ...indentStyle, cursor: 'pointer' }}
        onClick={handleSelect}
      >
        {/* Expand/collapse icon */}
        <span
          className="me-2"
          style={{ width: '20px', cursor: hasChildren ? 'pointer' : 'default' }}
          onClick={(e) => {
            e.stopPropagation();
            toggleExpand();
          }}
        >
          {loadingChildren ? (
            <i className="bi bi-hourglass-split text-muted"></i>
          ) : hasChildren ? (
            isExpanded ? (
              <i className="bi bi-chevron-down"></i>
            ) : (
              <i className="bi bi-chevron-right"></i>
            )
          ) : (
            <i className="bi bi-circle-fill" style={{ fontSize: '6px' }}></i>
          )}
        </span>

        {/* Workgroup icon */}
        <i className="bi bi-folder2 me-2 text-primary"></i>

        {/* Workgroup name */}
        <span className="flex-grow-1 fw-medium">{workgroup.name}</span>

        {workgroup.enabled === false && (
          <span className="badge bg-secondary me-2">Disabled</span>
        )}

        {/* Depth badge */}
        <span className="badge bg-secondary me-2">
          L{workgroup.depth}
        </span>

        {/* Child count */}
        {hasChildren && (
          <span className="badge bg-info me-2">
            {workgroup.childCount} {workgroup.childCount === 1 ? 'child' : 'children'}
          </span>
        )}

        {/* Add child button */}
        {workgroup.depth < 5 && onCreateChild && (
          <button
            className="btn btn-sm btn-outline-primary"
            onClick={handleCreateChild}
            title="Add child workgroup"
          >
            <i className="bi bi-plus-circle"></i>
          </button>
        )}
      </div>

      {/* Error message */}
      {error && (
        <div className="alert alert-danger mx-3 my-2" style={indentStyle}>
          <i className="bi bi-exclamation-triangle"></i> {error}
        </div>
      )}

      {/* Children */}
      {isExpanded && children.length > 0 && (
        <div>
          {children
            .filter((child) => showAwsWorkgroups || !isAwsWorkgroup(child.name))
            .map((child) => (
              <TreeNode
                key={child.id}
                workgroup={child}
                level={level + 1}
                onSelectWorkgroup={onSelectWorkgroup}
                onCreateChild={onCreateChild}
                selectedWorkgroupId={selectedWorkgroupId}
                showAwsWorkgroups={showAwsWorkgroups}
              />
            ))}
        </div>
      )}
    </div>
  );
};

const WorkgroupTree: React.FC<WorkgroupTreeProps> = ({
  onSelectWorkgroup,
  onCreateChild,
  selectedWorkgroupId,
  showAwsWorkgroups = false
}) => {
  const [rootWorkgroups, setRootWorkgroups] = useState<WorkgroupResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRootWorkgroups();
  }, []);

  const fetchRootWorkgroups = async () => {
    setLoading(true);
    setError(null);
    try {
      const roots = await getRootWorkgroups();
      setRootWorkgroups(roots);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load workgroups');
      console.error('Failed to load root workgroups:', err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
        <p className="text-muted mt-2">Loading workgroup tree...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="alert alert-danger">
        <i className="bi bi-exclamation-triangle"></i> {error}
        <button
          className="btn btn-sm btn-outline-danger ms-3"
          onClick={fetchRootWorkgroups}
        >
          Retry
        </button>
      </div>
    );
  }

  const visibleRoots = rootWorkgroups.filter(
    (wg) => showAwsWorkgroups || !isAwsWorkgroup(wg.name)
  );

  if (visibleRoots.length === 0) {
    return (
      <div className="text-center py-5 text-muted">
        <i className="bi bi-folder2-open" style={{ fontSize: '48px' }}></i>
        <p className="mt-3">No workgroups found</p>
        <p className="small">
          {rootWorkgroups.length > 0
            ? 'AWS- workgroups are hidden. Enable "Show AWS- workgroups" to see them.'
            : 'No visible workgroups are available.'}
        </p>
      </div>
    );
  }

  return (
    <div className="workgroup-tree border rounded">
      <div className="bg-light px-3 py-2 border-bottom">
        <h6 className="mb-0">
          <i className="bi bi-diagram-3"></i> Workgroup Hierarchy
        </h6>
      </div>
      <div className="tree-content">
        {visibleRoots.map((workgroup) => (
          <TreeNode
            key={workgroup.id}
            workgroup={workgroup}
            level={0}
            onSelectWorkgroup={onSelectWorkgroup}
            onCreateChild={onCreateChild}
            selectedWorkgroupId={selectedWorkgroupId}
            showAwsWorkgroups={showAwsWorkgroups}
          />
        ))}
      </div>
    </div>
  );
};

export default WorkgroupTree;
import { authenticatedPost, authenticatedGet, authenticatedPut, authenticatedDelete } from '../utils/auth';

/**
 * Service for Workgroup API operations
 * Features: 008-create-an-additional, 040-nested-workgroups
 */

/**
 * Breadcrumb item for ancestor path navigation
 * Feature 040: Nested Workgroups
 */
export interface BreadcrumbItem {
  id: number;
  name: string;
}

/**
 * Workgroup DTO with hierarchy information
 * Feature 040: Nested Workgroups
 */
export interface WorkgroupResponse {
  id: number;
  name: string;
  description?: string;
  ownerEmail?: string | null;
  enabled?: boolean;
  parentId?: number;
  depth: number;
  childCount: number;
  hasChildren: boolean;
  ancestors: BreadcrumbItem[];
  createdAt: string;
  updatedAt: string;
  version: number;
}

/**
 * True when a workgroup's name marks it as AD-imported (the `adread --import`
 * tool names workgroups after `AWS-`-prefixed Azure AD groups). Matched
 * case-insensitively to mirror the Graph-side `AWS-/aws-/Aws-` prefixes.
 * The workgroup UI hides these by default behind a "Show AWS- workgroups" toggle.
 */
export const isAwsWorkgroup = (name: string): boolean =>
  name.trim().toUpperCase().startsWith('AWS-');

/**
 * Request to create a child workgroup
 * Feature 040: Nested Workgroups (User Story 1)
 */
export interface CreateChildWorkgroupRequest {
  name: string;
  description?: string;
}

/**
 * Request to move a workgroup
 * Feature 040: Nested Workgroups (User Story 3)
 */
export interface MoveWorkgroupRequest {
  newParentId?: number | null;
}

/**
 * Request to create a root-level workgroup
 * Feature 008: Workgroup Management
 */
export interface CreateWorkgroupRequest {
  name: string;
  description?: string;
  criticality?: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
}

/**
 * Create a child workgroup under a parent
 * Feature 040: Nested Workgroups (User Story 1)
 *
 * @param parentId ID of parent workgroup
 * @param request Create child workgroup request
 * @returns Created child workgroup with hierarchy info
 */
export async function createChildWorkgroup(
  parentId: number,
  request: CreateChildWorkgroupRequest
): Promise<WorkgroupResponse> {
  const response = await authenticatedPost(
    `/api/workgroups/${parentId}/children`,
    request
  );
  if (!response.ok) {
    throw new Error(await extractErrorMessage(response, 'Failed to create child workgroup'));
  }
  return await response.json();
}

/**
 * Get all direct children of a workgroup
 * Feature 040: Nested Workgroups (User Story 2)
 *
 * @param parentId ID of parent workgroup
 * @returns List of direct children
 */
export async function getWorkgroupChildren(
  parentId: number
): Promise<WorkgroupResponse[]> {
  const response = await authenticatedGet(
    `/api/workgroups/${parentId}/children`
  );
  return await response.json();
}

/**
 * Get all root-level workgroups (no parent)
 * Feature 040: Nested Workgroups (User Story 2)
 *
 * @returns List of root-level workgroups
 */
export async function getRootWorkgroups(): Promise<WorkgroupResponse[]> {
  const response = await authenticatedGet(
    `/api/workgroups/root`
  );
  return await response.json();
}

/**
 * Get every workgroup visible to the caller in one flat response.
 * Each entry carries parentId/hasChildren, so tree views rebuild the
 * hierarchy locally instead of requesting children node by node.
 *
 * @returns All visible workgroups (flat list with parent links)
 */
export async function getWorkgroupTree(): Promise<WorkgroupResponse[]> {
  const response = await authenticatedGet(
    `/api/workgroups/tree`
  );
  return await response.json();
}

/**
 * Get all ancestors from root to immediate parent
 * Feature 040: Nested Workgroups (User Story 5)
 *
 * @param workgroupId ID of workgroup
 * @returns List of ancestors (root first, immediate parent last)
 */
export async function getWorkgroupAncestors(
  workgroupId: number
): Promise<BreadcrumbItem[]> {
  const response = await authenticatedGet(
    `/api/workgroups/${workgroupId}/ancestors`
  );
  return await response.json();
}

/**
 * Get all descendants (entire subtree)
 * Feature 040: Nested Workgroups (User Story 2)
 *
 * @param workgroupId ID of root workgroup
 * @returns List of all descendants
 */
export async function getWorkgroupDescendants(
  workgroupId: number
): Promise<WorkgroupResponse[]> {
  const response = await authenticatedGet(
    `/api/workgroups/${workgroupId}/descendants`
  );
  return await response.json();
}

/**
 * Move a workgroup to a new parent
 * Feature 040: Nested Workgroups (User Story 3)
 *
 * @param workgroupId ID of workgroup to move
 * @param request Move workgroup request (null newParentId moves to root)
 * @returns Updated workgroup
 */
export async function moveWorkgroup(
  workgroupId: number,
  request: MoveWorkgroupRequest
): Promise<WorkgroupResponse> {
  const response = await authenticatedPut(
    `/api/workgroups/${workgroupId}/parent`,
    request
  );
  if (!response.ok) {
    throw new Error(await extractErrorMessage(response, 'Failed to move workgroup'));
  }
  return await response.json();
}

/**
 * Read the server's error message off a failed Response, falling back to a
 * generic message plus the status code. Exported so the workgroup modals share
 * this one implementation rather than each growing their own.
 */
export async function extractErrorMessage(response: Response, fallback: string): Promise<string> {
  try {
    const text = await response.text();
    if (!text) return `${fallback} (HTTP ${response.status})`;
    try {
      const body = JSON.parse(text);
      if (body && typeof body.error === 'string') return body.error;
      if (body && typeof body.message === 'string') return body.message;
    } catch {
      return text;
    }
  } catch {
    // ignore
  }
  return `${fallback} (HTTP ${response.status})`;
}

/**
 * Delete a workgroup (children are promoted to grandparent)
 * Feature 040: Nested Workgroups (User Story 4)
 *
 * @param workgroupId ID of workgroup to delete
 */
export async function deleteWorkgroup(workgroupId: number): Promise<void> {
  await authenticatedDelete(`/api/workgroups/${workgroupId}`);
}

/**
 * Create a root-level workgroup
 * Feature 008: Workgroup Management
 *
 * @param request Create workgroup request
 * @returns Created workgroup
 */
export async function createWorkgroup(
  request: CreateWorkgroupRequest
): Promise<WorkgroupResponse> {
  const response = await authenticatedPost('/api/workgroups', request);
  return await response.json();
}

/**
 * Get workgroup details by ID
 * Feature 008: Workgroup Management
 *
 * @param workgroupId ID of workgroup
 * @returns Workgroup with hierarchy information
 */
export async function getWorkgroupById(
  workgroupId: number
): Promise<WorkgroupResponse> {
  const response = await authenticatedGet(
    `/api/workgroups/${workgroupId}`
  );
  return await response.json();
}
