    command -v "$command_name" >/dev/null || {
        echo "Missing required command: $command_name" >&2; exit 2;
    }
done

# Fixed test ports must be free; never displace another stack.
if [[ "$DB_ONLY" == false ]]; then
    for port in "$BACKEND_PORT" "$FRONTEND_PORT" "$SMTP_PORT"; do
        if lsof -nP -iTCP:"$port" -sTCP:LISTEN >/dev/null 2>&1; then
            echo "Test port $port is already occupied; no database was changed" >&2
            exit 2
        fi
    done
fi

db_admin() { mariadb --batch --skip-column-names "$@"; }
MANIFEST_DIR="$REPO_ROOT/.e2e-logs/isolated-manifests"
mkdir -p "$MANIFEST_DIR"

# Only schemas carrying both our ownership table and matching manifest are eligible.
# A live runner PID prevents another invocation from deleting an active test.
clean_abandoned() {
    local schema marker owner_label owner_pid owner_token manifest
    while IFS= read -r schema; do
        [[ "$schema" =~ ^secman_e2e_[a-f0-9]{16}$ ]] || continue
        manifest="$MANIFEST_DIR/$schema.json"
        marker="$(db_admin -e "SELECT CONCAT(owner_label, ':', owner_pid, ':', owner_token) FROM \`$schema\`.\`$MARKER_TABLE\` LIMIT 1" 2>/dev/null || true)"
        IFS=: read -r owner_label owner_pid owner_token <<< "$marker"
        if [[ "$owner_label" != "$OWNER_LABEL" || ! "$owner_pid" =~ ^[0-9]+$ ||
              ! "$owner_token" =~ ^[a-f0-9]{32}$ || ! -f "$manifest" ]] ||
            ! jq -e --arg schema "$schema" --arg label "$owner_label" \
                --arg token "$owner_token" --argjson pid "$owner_pid" \
                '.schema==$schema and .ownerLabel==$label and .ownerToken==$token and .ownerPid==$pid' \
                "$manifest" >/dev/null 2>&1; then
            echo "Preserving unverified database $schema" >&2
            continue
        fi
        if kill -0 "$owner_pid" 2>/dev/null; then
            echo "Preserving active test database $schema (runner $owner_pid)" >&2
            continue
        fi
        db_admin -e "DROP DATABASE \`$schema\`" 
        db_admin -e "DROP USER IF EXISTS '$schema'@'localhost', '$schema'@'127.0.0.1'"
        rm -f "$manifest"
        echo "Removed abandoned test database $schema" >&2
    done < <(db_admin -e "SELECT SCHEMA_NAME FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME LIKE 'secman_e2e_%'")
}

clean_abandoned

RUN_ID="$(openssl rand -hex 8)"
DB_NAME="secman_e2e_${RUN_ID}"
DB_PASSWORD="$(openssl rand -hex 24)"
OWNER_TOKEN="$(openssl rand -hex 16)"
LOG_DIR="$REPO_ROOT/.e2e-logs/isolated-$RUN_ID"
MANIFEST_FILE="$MANIFEST_DIR/$DB_NAME.json"
mkdir -p "$LOG_DIR"

CREATED_DB=false
FRONTEND_COPY=""
smtp_pid=""
finish() {
    local result="$1" marker
    trap - EXIT
    if declare -f stop_own_listener >/dev/null; then
        if [[ -n "$FRONTEND_COPY" ]]; then
            stop_own_listener "$FRONTEND_PORT" "$FRONTEND_COPY" || result=1
        fi
        stop_own_listener "$BACKEND_PORT" "$REPO_ROOT/src/backendng" || result=1
    fi
    if [[ -n "$smtp_pid" ]] && kill -0 "$smtp_pid" 2>/dev/null; then
        kill "$smtp_pid" || result=1
    fi
    if [[ -n "$FRONTEND_COPY" && -d "$FRONTEND_COPY" &&
          "$(basename "$FRONTEND_COPY")" == secman-frontend-e2e.* ]]; then
        rm -rf "$FRONTEND_COPY"
    fi
    if [[ "$CREATED_DB" == true ]]; then
        marker="$(db_admin -e "SELECT owner_token FROM \`$DB_NAME\`.\`$MARKER_TABLE\` LIMIT 1" 2>/dev/null || true)"
        if [[ "$marker" == "$OWNER_TOKEN" ]] &&
            jq -e --arg schema "$DB_NAME" --arg token "$OWNER_TOKEN" \
                '.schema==$schema and .ownerToken==$token' "$MANIFEST_FILE" >/dev/null 2>&1; then
            if db_admin -e "DROP DATABASE \`$DB_NAME\`" &&
                db_admin -e "DROP USER IF EXISTS '$DB_NAME'@'localhost', '$DB_NAME'@'127.0.0.1'"; then
                rm -f "$MANIFEST_FILE"
            else
                result=1
            fi
        else
            echo "Ownership marker changed; preserving $DB_NAME for review" >&2
            result=1
#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
if [[ -z "${SECMAN_TEST_ISOLATED_DB:-}" ]]; then
  exec "$SCRIPT_DIR/../scripts/test/run-isolated-e2e.sh" -- bash -c \
    './scripts/test/provision-test-user.sh && SECMAN_BACKEND_URL="$FRONTEND_URL" ./tests/js-error-scanner-pp.sh'
fi
# shellcheck source=lib/secman-test-tls.sh
source "$SCRIPT_DIR/lib/secman-test-tls.sh"

## TLS/host policy enforcement
CURRENT_BACKEND_URL="${SECMAN_BACKEND_URL:-}"
if [[ -n "${SECMAN_TEST_ISOLATED_DB:-}" ]]; then
  BASE_URL="${SECMAN_E2E_BACKEND_URL:-}"
  source "$SCRIPT_DIR/../scripts/test/lib/isolated-target.sh"
  secman_test_require_isolated
  [[ "$CURRENT_BACKEND_URL" == "${SECMAN_E2E_FRONTEND_URL:-}" ]] || {
    echo "ERROR: scanner URL is not the isolated frontend" >&2; exit 2;
  }
elif [ -n "$CURRENT_BACKEND_URL" ] && [ "$CURRENT_BACKEND_URL" != "https://secman.covestro.net" ] && [[ "$CURRENT_BACKEND_URL" != pass://* ]]; then
  echo "ERROR: SECMAN_BACKEND_URL must be https://secman.covestro.net (or pass:// URI)."
  exit 2
fi

# --- Local dev auto-detection (disabled for policy compliance) ---
# If a local frontend dev server is reachable on the configured port, override
# the backend URL to point at it. This prevents the scanner from accidentally
# targeting the production host (pass://Test/SECMAN/SECMAN_HOST) when an e2e
# run is clearly aimed at the local stack started by ./scripts/startfrontenddev.sh.
#
# Detection rules:
#   - SECMAN_BACKEND_URL is "preference-bearing" only when it starts with
#     http:// or https://. If it's unset OR still a pass:// URI, the user has
#     expressed no explicit preference and we may auto-substitute localhost.
#   - We probe TCP port reachability via bash's /dev/tcp (no curl/nc needed,
#     no HTTP-status pitfalls like 302/401 on the Astro root page).
LOCAL_FRONTEND_HOST="${SECMAN_LOCAL_FRONTEND_HOST:-localhost}"
LOCAL_FRONTEND_PORT="${SECMAN_LOCAL_FRONTEND_PORT:-4321}"
LOCAL_FRONTEND_URL="http://${LOCAL_FRONTEND_HOST}:${LOCAL_FRONTEND_PORT}"

probe_tcp() {
  # Returns 0 if TCP connect to $1:$2 succeeds, 1 otherwise. Pure bash.
  (exec 3<>/dev/tcp/"$1"/"$2") 2>/dev/null && {
    exec 3<&- 3>&-
    return 0
  }
  return 1
}

CURRENT_BACKEND_URL="${SECMAN_BACKEND_URL:-}"
USER_PROVIDED_HTTP=false
case "$CURRENT_BACKEND_URL" in
  http://*|https://*) USER_PROVIDED_HTTP=true ;;
esac
## User preferences

- For a “full review” that should “identify [issues] and propose a fix,” inspect secondary projections and delivery paths—exports, notifications, filters, reports, UI consumers, and revocation—not only the primary asset list. [Task 1]
- When the requested policy names workgroups, mapped AWS accounts, and mapped AD domains, state existing policy exceptions (ADMIN/SECCHAMPION global access, enabled workgroup grants, selected incoming sharing) rather than silently treating the literal wording as exhaustive. [Task 1]

## Reusable knowledge

- Ordinary-user visibility is the union of enabled direct workgroup asset access, personal email-keyed AWS/AD mappings, enabled workgroup AWS/AD grants, and selected directional AWS sharing. ADMIN and SECCHAMPION are global; ownership, creator/uploader metadata, and parent-workgroup relationships are not central grants. [Task 1]
- `AssetFilterService` / `AssetAccessSql` govern the primary list. Identity changes/disabled users are rejected; MCP computes live scope; queued vulnerability exports bind actor identity plus a scope digest and revalidate during processing/download. [Task 1]
- Authorize every asset-derived projection against current actor/recipient scope: use scoped DTOs and scoped database/count queries before pagination, filter linked assets before projection/export, make denied-existing and nonexistent IDs indistinguishable, resolve email recipients through live grants and recheck before delivery. [Task 1]
- The ten static findings cover application detail/export linked assets, VULN CrowdStrike hostname/instance lookup, RISK/REPORT content, demand history and picker, EOL recipients, filter/autocomplete metadata, ID oracle behavior, dashboard revocation, and outdated-asset pagination. Consult the summary before selecting remediation order. [Task 1]

## Failures and how to do differently

- The review is not runtime proof. Reproduce highest-risk paths with a disposable database and disjoint workgroup/AWS/domain grants; test direct REST, UI projections, exports, notification recipients, and reads after revocation. [Task 1]
- The worktree was dirty and no changes were made; preserve unrelated changes. Scan artifact submission initially rejected unsupported coverage fields, so follow the tool schema exactly. [Task 1]

